  const money=n=>Number.isFinite(Number(n))?new Intl.NumberFormat('es-UY',{style:'currency',currency:'USD'}).format(Number(n)):'—';
  const uyu=n=>Number.isFinite(Number(n))?new Intl.NumberFormat('es-UY',{style:'currency',currency:'UYU',maximumFractionDigits:0}).format(Number(n)):'—';
  const number=n=>{const v=Number(n);return Number.isFinite(v)?Math.max(0,v):0};
