  function toast(msg,error=false){$('toast')?.remove();const el=document.createElement('div');el.id='toast';el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'alert':'check',17)+`<span>${esc(msg)}</span>`;document.body.appendChild(el);clearTimeout(toastTime);toastTime=setTimeout(()=>el.remove(),3800)}
  const route=()=>decodeURIComponent(location.hash.replace(/^#\/?/,'')).split('?')[0]||'inicio';
