  const fmtResult=q=>q.total==null?'A confirmar':money(q.total);
  function shopLink(shop,q){const text=encodeURIComponent(q.trim());if(shop==='amazon')return 'https://www.amazon.com/s?k='+text;if(shop==='mercado')return 'https://listado.mercadolibre.com.uy/'+encodeURIComponent(q.trim().toLowerCase().replace(/\s+/g,'-'));if(shop==='ebay')return 'https://www.ebay.com/sch/i.html?_nkw='+text;if(shop==='aliexpress')return 'https://www.aliexpress.com/w/wholesale-'+text+'.html';return SOURCE.tiendamia}
